import { ref, watch, type Ref } from 'vue'
import services from '@/services'
import Util from '@/utility/util'
import { formatMonthLabel } from '@/dashboard/utils/date'
import { milestoneDate, parseMilestoneName, type MilestoneSide } from '@/dashboard/utils/milestones'
import { classifyTask, isTrue, projectStatusFromMilestones } from '@/dashboard/utils/projectStatus'
import type { FedSearchItem } from './useFederatedSearch'
import type { Milestone, StatusKey } from '@/dashboard/types/project'

/**
 * Only projects whose name starts with one of these prefixes (case-insensitive) are
 * loaded and shown on the dashboard. Leave the list empty to include all projects.
 */
export const PROJECT_NAME_PREFIXES: readonly string[] = [
  'STAND COMP',
  'HANDLE BAR',
  'MUFFLER ASSY EXH',
]

/**
 * Image URL shown in the Image column of the Timeline and Event Status tables:
 * the federated-search `preview_url` attribute of the project.
 */
function itemImageUrl(item: FedSearchItem): string {
  const url = item.preview_url
  return typeof url === 'string' ? url.trim() : ''
}

export interface ProjectTask {
  id?: string
  title?: string
  type?: string
  nlsType?: string
  /** API returns "TRUE" / "FALSE" strings */
  isTypeMilestone?: string | boolean
  isTypeGate?: string | boolean
  isSummaryTask?: string | boolean
  estimatedStartDate?: string
  dueDate?: string
  forecastFinishDate?: string
  forecastStartDate?: string
  percentComplete?: string | number
  status?: string
  state?: string
  sequenceOrder?: string | number
  criticalTask?: string | boolean
  /** Nested child tasks (Milestones/Gates sit inside Phase.children[]) */
  children?: ProjectTask[]
  [key: string]: unknown
}

export interface ProjectDetail {
  projectId: string
  projectLabel: string
  title?: string
  status?: string
  percentComplete?: number
  estimatedStartDate?: string
  estimatedFinishDate?: string
  /** Flat list of ALL tasks (phases + their children) */
  tasks: ProjectTask[]
  /** Only tasks where isTypeMilestone === "TRUE" */
  milestones: ProjectTask[]
  /** Only tasks where isTypeGate === "TRUE" */
  gates: ProjectTask[]
  /** Top-level tasks (usually phases), before flattening */
  phases: ProjectTask[]
  /** Status derived from the project's milestones (the API's project status is empty) */
  statusKey: StatusKey
  /** Collaborative space the project belongs to ('' when search did not return one) */
  collabSpace: string
  /** Custom project attributes (empty string when the project does not have them) */
  attributes: ProjectAttributes
  /** Project baselines, latest first ([] when the project has none) */
  baselines: ProjectBaseline[]
}

export interface ProjectBaseline {
  id: string
  /** e.g. "HANDLE BAR BASELINE 1" */
  title: string
  /** Creation time (ISO); baselines are ordered by it, latest first */
  originated: string
  /** Baseline's project estimated finish date */
  estimatedFinishDate: string
  /** The baseline's milestone tasks ([] when they could not be loaded) */
  milestones: ProjectTask[]
}

export interface ProjectAttributes {
  location: string
  model: string
  volDay: string
  pl: string
  /** Image URL from the federated-search `preview_url` attribute */
  imageUrl: string
  /** Project description (details API, else federated search); shown as Remarks */
  description: string
  /** "CustomerQAV" project attribute from the details API */
  customerQav: string
  /** Titles of the project's attachments of type Physical Product (documents API) */
  physicalProducts: string[]
}

// ─── helpers ────────────────────────────────────────────────────────────────

/** Recursively flattens a task tree (phases → children) into a single list. */
function flattenTasks(tasks: ProjectTask[]): ProjectTask[] {
  const flat: ProjectTask[] = []
  for (const task of tasks) {
    flat.push(task)
    if (Array.isArray(task.children) && task.children.length > 0) {
      flat.push(...flattenTasks(task.children))
    }
  }
  return flat
}

/** Timeline marker for a milestone, labelled with its event (e.g. "PP0"). */
function taskToMilestone(task: ProjectTask): Milestone {
  const date = milestoneDate(task)
  return {
    dateLabel: date ? formatMonthLabel(date) : '',
    kind: parseMilestoneName(task.title)?.event ?? '',
    status: classifyTask(task),
  }
}

/** Markers for one side's milestones (sorted by sequence) of a project. */
function markersForSide(milestones: ProjectTask[], side: MilestoneSide): Milestone[] {
  return milestones
    .filter((m) => parseMilestoneName(m.title)?.side === side)
    .map(taskToMilestone)
}

/**
 * The project-details API returns the project either directly on the root,
 * or as the first entry of a `data` / `member` array.
 */
function extractProject(data: Record<string, unknown>): Record<string, unknown> {
  if (Array.isArray(data['data']) && data['data'].length > 0) {
    return data['data'][0] as Record<string, unknown>
  }
  return data
}

function firstEntryTasks(list: unknown): ProjectTask[] | null {
  if (!Array.isArray(list)) return null
  const first = list[0] as Record<string, unknown> | undefined
  return first && Array.isArray(first['tasks']) ? (first['tasks'] as ProjectTask[]) : null
}

/** Checked in order: { data: [{ tasks }] }, { tasks }, { member: [{ tasks }] }. */
function extractTasks(data: Record<string, unknown>): ProjectTask[] {
  return (
    firstEntryTasks(data['data']) ??
    (Array.isArray(data['tasks']) ? (data['tasks'] as ProjectTask[]) : null) ??
    firstEntryTasks(data['member']) ??
    []
  )
}

function itemLabel(item: FedSearchItem | undefined, fallback = ''): string {
  return (item?.['ds6w:label'] ?? item?.['ds6w:identifier'] ?? fallback) as string
}

/** Search attributes holding the project description, in order of preference. */
const SEARCH_DESCRIPTION_ATTRIBUTES = ['ds6w:description', 'dcterms:description'] as const

/** Project description from the federated-search item ('' when it has none). */
function itemDescription(item: FedSearchItem): string {
  for (const name of SEARCH_DESCRIPTION_ATTRIBUTES) {
    const value = item[name]
    if (typeof value === 'string' && value.trim()) return value.trim()
  }
  return ''
}

/**
 * Only search results of this type are projects. Others (e.g. "Project Baseline", whose
 * names start like their project's) are skipped.
 */
const PROJECT_TYPE = 'project space'

/** Search item type, e.g. "Project Space" ('' when search did not return one). */
function itemType(item: FedSearchItem): string {
  const type = item['ds6w:what/ds6w:type'] ?? item['type']
  return typeof type === 'string' ? type.trim().toLowerCase() : ''
}

/**
 * True when the search item is a project the dashboard shows: a Project Space (items
 * without a type are kept) whose name matches the prefix rule.
 */
export function matchesProjectPrefix(item: FedSearchItem): boolean {
  const type = itemType(item)
  if (type && type !== PROJECT_TYPE) return false
  if (!PROJECT_NAME_PREFIXES.length) return true
  const name = itemLabel(item).trim().toUpperCase()
  return PROJECT_NAME_PREFIXES.some((prefix) => name.startsWith(prefix.toUpperCase()))
}

/**
 * Search attributes holding the collaborative space, in order of preference. Search returns
 * it as the facet "ds6w:where/ds6w:context/ds6w:project" (e.g. "Common Space").
 */
const COLLAB_SPACE_FIELDS = ['ds6w:where/ds6w:context/ds6w:project', 'ds6w:project']

/** Collaborative space of a search item; '' when missing. */
export function itemCollabSpace(item: FedSearchItem): string {
  const field = COLLAB_SPACE_FIELDS.find((name) => item[name] !== undefined && item[name] !== '')
  const value = field ? item[field] : undefined
  const first = Array.isArray(value) ? value[0] : value
  return first === undefined || first === null ? '' : String(first).trim()
}

/**
 * Reads a project attribute by name, ignoring case ("VolDay" / "volday"),
 * as returned with `$fields=All`. Empty string when absent or empty.
 */
function readAttribute(project: Record<string, unknown>, name: string): string {
  const wanted = name.toLowerCase()
  const key = Object.keys(project).find((k) => k.toLowerCase() === wanted)
  const value = key === undefined ? undefined : project[key]
  return value === undefined || value === null ? '' : String(value).trim()
}

interface ParsedProject {
  detail: ProjectDetail
  customerMarkers: Milestone[]
  indoMarkers: Milestone[]
}

// ─── project attachments (documents API) ────────────────────────────────────

/** Attachment type shown in the Model column (matched against the type and its display name). */
const PHYSICAL_PRODUCT_TYPES = ['physical product', 'vpmreference']

/** First non-empty string among `keys` on `obj`. */
function firstString(obj: Record<string, unknown> | undefined, keys: string[]): string {
  if (!obj) return ''
  for (const key of keys) {
    const value = obj[key]
    if (typeof value === 'string' && value.trim()) return value.trim()
  }
  return ''
}

/** True when the attachment is a Physical Product (checks type and NLS type, any case). */
function isPhysicalProduct(doc: Record<string, unknown>): boolean {
  const elements = doc['dataelements'] as Record<string, unknown> | undefined
  const types = [
    doc['type'],
    doc['typeNLS'],
    doc['nlsType'],
    elements?.['type'],
    elements?.['typeNLS'],
    elements?.['nlsType'],
  ]
  return types.some(
    (t) => typeof t === 'string' && PHYSICAL_PRODUCT_TYPES.includes(t.trim().toLowerCase()),
  )
}

/** Physical Product attachments in a documents response ([] if the request failed). */
function parsePhysicalProducts(raw: unknown): Record<string, unknown>[] {
  const response = raw as Record<string, unknown> | null
  if (!response || response['isAxiosError'] === true) return []

  const body = response['data'] as Record<string, unknown> | unknown[] | null
  const docs = Array.isArray(body)
    ? body
    : body && Array.isArray(body['data'])
      ? (body['data'] as unknown[])
      : []

  return docs
    .filter((d): d is Record<string, unknown> => !!d && typeof d === 'object')
    .filter(isPhysicalProduct)
}

/** Title (else name) as given by the documents API; for Physical Products often the "prd-…" name. */
function documentTitle(doc: Record<string, unknown>): string {
  const elements = doc['dataelements'] as Record<string, unknown> | undefined
  return firstString(elements, ['title', 'name']) || firstString(doc, ['title', 'name'])
}

/** Display title of a Physical Product from the engineering item API ('' when unavailable). */
async function engineeringItemTitle(itemId: string, secCtx: string): Promise<string> {
  if (!itemId) return ''
  const data = responseBody(await services.enovia().getEngineeringItem(itemId, secCtx))
  if (!data) return ''
  const member = Array.isArray(data['member']) ? (data['member'][0] as Record<string, unknown>) : data
  return firstString(member, ['title'])
}

/**
 * Title of the project's Physical Product attachment, as a one-entry list ([] when it has
 * none or the request fails). Revisions share the title, so only the first one is looked up.
 */
async function fetchPhysicalProducts(id: string, secCtx: string): Promise<string[]> {
  try {
    const [first] = parsePhysicalProducts(await services.enovia().getProjectDocuments(id, secCtx))
    if (!first) return []
    let title = ''
    try {
      title = await engineeringItemTitle(String(first['id'] ?? ''), secCtx)
    } catch (err: unknown) {
      console.warn(`[useProjectMilestones] Title of Physical Product ${String(first['id'])} failed:`, err)
    }
    title = title || documentTitle(first)
    return title ? [title] : []
  } catch (err: unknown) {
    console.warn(`[useProjectMilestones] Attachments of project ${id} failed:`, err)
    return []
  }
}

/** Response body as an object, or null when the request failed (errors are resolved, not thrown). */
function responseBody(raw: unknown): Record<string, unknown> | null {
  const response = raw as Record<string, unknown> | null
  if (!response || response['isAxiosError'] === true) return null
  const body = response['data']
  return body && typeof body === 'object' && !Array.isArray(body)
    ? (body as Record<string, unknown>)
    : {}
}

/** Milestone tasks of a task list, in sequence order. */
function milestonesOf(tasks: ProjectTask[]): ProjectTask[] {
  return tasks
    .filter((t) => isTrue(t.isTypeMilestone))
    .sort((a, b) => Number(a.sequenceOrder ?? 0) - Number(b.sequenceOrder ?? 0))
}

// ─── project baselines ──────────────────────────────────────────────────────

/** Baselines listed in a "$include=baselines" response, latest first (no milestones yet). */
function parseBaselineList(raw: unknown): ProjectBaseline[] {
  const data = responseBody(raw)
  if (!data) return []
  const project = extractProject(data)
  const related = project['relateddata'] as Record<string, unknown> | undefined
  const list = Array.isArray(related?.['baselines']) ? (related!['baselines'] as unknown[]) : []

  return list
    .filter((b): b is Record<string, unknown> => !!b && typeof b === 'object')
    .map((b) => {
      const el = (b['dataelements'] ?? {}) as Record<string, unknown>
      return {
        id: String(b['id'] ?? ''),
        title: firstString(el, ['title', 'name']),
        originated: firstString(el, ['originated']),
        estimatedFinishDate: firstString(el, ['estimatedFinishDate']),
        milestones: [],
      }
    })
    .filter((b) => b.id)
    .sort((a, b) => b.originated.localeCompare(a.originated))
}

/** A project's baselines with their milestones, latest first; [] when the request fails. */
async function fetchBaselines(id: string, secCtx: string): Promise<ProjectBaseline[]> {
  try {
    const baselines = parseBaselineList(await services.enovia().getProjectBaselines(id, secCtx))
    // A baseline is a project itself: its milestones come from the project-details call.
    await Promise.all(
      baselines.map(async (baseline) => {
        try {
          const data = responseBody(await services.enovia().getProjectDetails(baseline.id, secCtx))
          if (data) baseline.milestones = milestonesOf(flattenTasks(extractTasks(data)))
        } catch (err: unknown) {
          console.warn(`[useProjectMilestones] Baseline ${baseline.id} failed:`, err)
        }
      }),
    )
    return baselines
  } catch (err: unknown) {
    console.warn(`[useProjectMilestones] Baselines of project ${id} failed:`, err)
    return []
  }
}

/** Turns one project-details response into dashboard data; null if the request failed. */
function parseProjectResponse(item: FedSearchItem, id: string, raw: unknown): ParsedProject | null {
  const data = responseBody(raw)
  if (!data) return null

  const project = extractProject(data)
  const topLevelTasks = extractTasks(data)
  const allTasks = flattenTasks(topLevelTasks)
  const milestoneTasks = milestonesOf(allTasks)

  return {
    detail: {
      projectId: id,
      projectLabel: itemLabel(item, id),
      title: project['title'] as string | undefined,
      status: project['status'] as string | undefined,
      percentComplete: parseFloat(String(project['percentComplete'] ?? '0')) || 0,
      estimatedStartDate: project['estimatedStartDate'] as string | undefined,
      estimatedFinishDate: project['estimatedFinishDate'] as string | undefined,
      tasks: allTasks,
      milestones: milestoneTasks,
      gates: allTasks.filter((t) => isTrue(t.isTypeGate)),
      phases: topLevelTasks,
      statusKey: projectStatusFromMilestones(milestoneTasks),
      collabSpace: itemCollabSpace(item),
      attributes: {
        location: readAttribute(project, 'Location'),
        model: readAttribute(project, 'Model'),
        volDay: readAttribute(project, 'VolDay'),
        pl: readAttribute(project, 'PL'),
        imageUrl: itemImageUrl(item),
        description: readAttribute(project, 'description') || itemDescription(item),
        customerQav: readAttribute(project, 'CustomerQAV'),
        physicalProducts: [],
      },
      baselines: [],
    },
    // Gates are not plotted.
    customerMarkers: markersForSide(milestoneTasks, 'CUSTOMER'),
    indoMarkers: markersForSide(milestoneTasks, 'INDO'),
  }
}

// ─── composable ─────────────────────────────────────────────────────────────

/** Project-detail requests in flight at once (keeps the browser and server responsive). */
const MAX_PARALLEL_REQUESTS = 10

/** While loading, partial results are pushed to the tabs at most this often. */
const PUBLISH_INTERVAL_MS = 400

export function useProjectMilestones(fedResults: Ref<FedSearchItem[]>) {
  const projects = ref<ProjectDetail[]>([])
  const loading = ref(false)
  const error = ref<string | null>(null)
  /** Customer milestones per project (circle markers), in sequence order. */
  const customerMarkersByProject = ref<Record<string, Milestone[]>>({})
  /** Indo milestones per project (square markers), in sequence order. */
  const indoMarkersByProject = ref<Record<string, Milestone[]>>({})
  /** Progress while loading: projects processed so far / projects to load. */
  const loadedCount = ref(0)
  const totalCount = ref(0)

  /** Incremented per fetch, so results of an outdated fetch are ignored. */
  let currentRun = 0

  async function fetchAll(searchItems: FedSearchItem[]) {
    if (!searchItems.length) return

    const items = searchItems.filter(matchesProjectPrefix)
    console.info(
      `[useProjectMilestones] Keeping ${items.length} of ${searchItems.length} projects ` +
        `(name starts with ${PROJECT_NAME_PREFIXES.map((p) => `"${p}"`).join(', ') || 'anything'}).`,
    )

    const run = ++currentRun
    const isCurrent = () => run === currentRun

    loading.value = true
    error.value = null
    loadedCount.value = 0
    totalCount.value = items.length

    const secCtx = Util.getCTX()
    if (!secCtx) {
      error.value = 'SecurityContext not available'
      loading.value = false
      return
    }

    // Indexed by search position, so the display order matches the search results.
    const parsed: Array<ParsedProject | null> = new Array(items.length).fill(null)
    let lastPublish = 0

    const publish = () => {
      if (!isCurrent()) return
      const done = parsed.filter((p): p is ParsedProject => p !== null)
      projects.value = done.map((p) => p.detail)
      customerMarkersByProject.value = Object.fromEntries(
        done.map((p) => [p.detail.projectId, p.customerMarkers]),
      )
      indoMarkersByProject.value = Object.fromEntries(
        done.map((p) => [p.detail.projectId, p.indoMarkers]),
      )
      lastPublish = Date.now()
    }

    let nextIndex = 0
    const worker = async () => {
      while (nextIndex < items.length && isCurrent()) {
        const idx = nextIndex++
        const item = items[idx]
        const id = item['resourceid'] as string | undefined
        if (id) {
          try {
            // Details, attachments and baselines load in parallel; only details are required.
            // eslint-disable-next-line no-await-in-loop
            const [raw, physicalProducts, baselines] = await Promise.all([
              services.enovia().getProjectDetails(id, secCtx),
              fetchPhysicalProducts(id, secCtx),
              fetchBaselines(id, secCtx),
            ])
            const result = parseProjectResponse(item, id, raw)
            if (result) {
              result.detail.attributes.physicalProducts = physicalProducts
              result.detail.baselines = baselines
            }
            parsed[idx] = result
          } catch (err: unknown) {
            console.warn(`[useProjectMilestones] Project ${id} failed:`, err)
          }
        }
        if (!isCurrent()) return
        loadedCount.value++
        if (Date.now() - lastPublish >= PUBLISH_INTERVAL_MS) publish()
      }
    }

    try {
      const workerCount = Math.min(MAX_PARALLEL_REQUESTS, items.length)
      await Promise.all(Array.from({ length: workerCount }, worker))
      publish()
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err)
      console.warn('[useProjectMilestones] Unexpected error:', message)
      if (isCurrent()) error.value = message
    } finally {
      if (isCurrent()) loading.value = false
    }
  }

  watch(
    fedResults,
    (items) => {
      if (items && items.length > 0) fetchAll(items)
    },
    { immediate: true },
  )

  return {
    projects,
    customerMarkersByProject,
    indoMarkersByProject,
    loading,
    loadedCount,
    totalCount,
    error,
    refetch: () => fetchAll(fedResults.value ?? []),
  }
}
